--
-- Table structure for table `account_titles`
--

DROP TABLE IF EXISTS `account_titles`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `account_titles` (
  `id` binary(16) NOT NULL COMMENT 'ULID',
  `entity_id` binary(16) NOT NULL,
  `code` varchar(16) NOT NULL COMMENT 'å‹˜å®šç§‘ç›®ã‚³ãƒ¼ãƒ‰',
  `name` varchar(128) NOT NULL COMMENT 'å‹˜å®šç§‘ç›®å',
  `category` varchar(32) NOT NULL COMMENT 'asset / liability / equity / revenue / expense',
  `normal_side` varchar(6) NOT NULL COMMENT 'debit / credit',
  `parent_id` binary(16) DEFAULT NULL COMMENT 'éšå±¤ï¼ˆnull ãªã‚‰æœ€ä¸Šä½ï¼‰',
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6),
  `updated_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) ON UPDATE current_timestamp(6),
  `deleted_at` timestamp(6) NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_account_titles__entity_code` (`entity_id`,`code`),
  KEY `idx_account_titles__parent` (`parent_id`),
  KEY `idx_account_titles__entity_active` (`entity_id`,`is_active`,`deleted_at`,`sort_order`),
  CONSTRAINT `fk_account_titles__entity` FOREIGN KEY (`entity_id`) REFERENCES `entities` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_account_titles__parent` FOREIGN KEY (`parent_id`) REFERENCES `account_titles` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `chk_account_titles__category` CHECK (`category` in ('asset','liability','equity','revenue','expense')),
  CONSTRAINT `chk_account_titles__normal_side` CHECK (`normal_side` in ('debit','credit'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='å‹˜å®šç§‘ç›®ï¼ˆChart of Accountsï¼‰';
