CREATE TABLE `api_tokens` (
  `id` binary(16) NOT NULL COMMENT 'ULID',
  `user_id` binary(16) NOT NULL COMMENT 'users.id ã¸ã® FK',
  `token_hash` char(64) NOT NULL COMMENT 'opaque token ã® SHA-256 hex',
  `token_prefix` char(8) NOT NULL COMMENT 'å¯è¦–ãƒ—ãƒ¬ãƒ•ã‚£ãƒƒã‚¯ã‚¹ï¼ˆãƒ­ã‚°ç…§åˆç”¨ï¼‰',
  `scopes` varchar(255) NOT NULL DEFAULT '' COMMENT 'space-separated ã‚¹ã‚³ãƒ¼ãƒ—',
  `issued_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6),
  `expires_at` timestamp(6) NOT NULL,
  `revoked_at` timestamp(6) NULL DEFAULT NULL,
  `last_used_at` timestamp(6) NULL DEFAULT NULL,
  `created_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6),
  `updated_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) ON UPDATE current_timestamp(6),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_api_tokens__hash` (`token_hash`),
  KEY `idx_api_tokens__user` (`user_id`,`revoked_at`,`expires_at`),
