) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='REST API Bearer ãƒˆãƒ¼ã‚¯ãƒ³ï¼ˆopaque, DB ä¿ç®¡ï¼‰';
