CREATE TABLE `journal_entry_lines` (
  `id` binary(16) NOT NULL COMMENT 'ULID',
  `entry_id` binary(16) NOT NULL,
  `line_no` smallint(6) NOT NULL COMMENT 'è¡Œç•ªå·ï¼ˆ1 èµ·ç•ªï¼‰',
  `side` varchar(6) NOT NULL COMMENT 'debit / credit',
  `account_title_id` binary(16) NOT NULL,
  `sub_account_title_id` binary(16) DEFAULT NULL,
  `amount` decimal(18,4) NOT NULL,
  `tax_rate_percent` decimal(5,2) NOT NULL DEFAULT 0.00 COMMENT 'è»½æ¸› 8%, æ¨™æº– 10% ç­‰',
  `tax_amount` decimal(18,4) NOT NULL DEFAULT 0.0000,
  `is_tax_reduced` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'è»½æ¸›ç¨ç‡å¯¾è±¡',
  `memo` varchar(255) NOT NULL DEFAULT '',
