  CONSTRAINT `fk_journal_lines__entry` FOREIGN KEY (`entry_id`) REFERENCES `journal_entries` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_journal_lines__sub` FOREIGN KEY (`sub_account_title_id`) REFERENCES `sub_account_titles` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `chk_journal_lines__side` CHECK (`side` in ('debit','credit')),
  CONSTRAINT `chk_journal_lines__amount` CHECK (`amount` >= 0),
  CONSTRAINT `chk_journal_lines__tax_amount` CHECK (`tax_amount` >= 0)
