--
-- Table structure for table `opening_balances`
--

DROP TABLE IF EXISTS `opening_balances`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `opening_balances` (
  `id` binary(16) NOT NULL COMMENT 'ULID',
  `entity_id` binary(16) NOT NULL,
  `fiscal_term_id` binary(16) NOT NULL,
  `account_title_id` binary(16) NOT NULL,
  `amount` decimal(18,4) NOT NULL DEFAULT 0.0000,
  `currency_code` char(3) NOT NULL DEFAULT 'JPY',
  `created_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6),
  `updated_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) ON UPDATE current_timestamp(6),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ob__at_ft` (`entity_id`,`fiscal_term_id`,`account_title_id`),
  KEY `fk_ob__ft` (`fiscal_term_id`),
  KEY `fk_ob__at` (`account_title_id`),
  CONSTRAINT `fk_ob__at` FOREIGN KEY (`account_title_id`) REFERENCES `account_titles` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_ob__entity` FOREIGN KEY (`entity_id`) REFERENCES `entities` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_ob__ft` FOREIGN KEY (`fiscal_term_id`) REFERENCES `fiscal_terms` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='æœŸé¦–æ®‹é«˜ï¼ˆå‹˜å®šç§‘ç›®åˆ¥ï¼‰ã€‚Ledger ã¨ BS ã®æœŸé¦–å€¤ç®—å‡ºã«ä½¿ç”¨ã€‚';
